//! Hyprland integration.
//!
//! AETHER only ever adds one clearly marked block to `hyprland.conf`. The main
//! config is backed up before every change. Generated visual settings live in
//! their own file and can be regenerated by `aether hyprland --apply`.

use crate::config::{hex_rgb, get_path};
use crate::fsutil;
use crate::paths::Paths;
use crate::report::{LogLevel, Reporter};
use crate::source::Source;
use anyhow::{Context, Result};
use serde_json::Value;
use std::fs;
use std::path::{Path, PathBuf};

pub const BEGIN_MARK: &str = "# >>> AETHER managed include >>>";
pub const END_MARK: &str = "# <<< AETHER managed include <<<";

#[derive(Debug, Clone)]
pub struct HyprSettings {
    pub gaps_in: i64,
    pub gaps_out: i64,
    pub border_size: i64,
    pub rounding: i64,
    pub blur: bool,
    pub shadows: bool,
    pub animation_preset: String,
}

impl Default for HyprSettings {
    fn default() -> Self {
        Self {
            gaps_in: 5,
            gaps_out: 12,
            border_size: 2,
            rounding: 16,
            blur: true,
            shadows: true,
            animation_preset: "aether".into(),
        }
    }
}

pub fn settings_from_config(config: &Value) -> HyprSettings {
    let mut settings = HyprSettings::default();
    settings.gaps_in = int_at(config, &["hyprland", "gapsIn"], 0, 64, settings.gaps_in);
    settings.gaps_out = int_at(config, &["hyprland", "gapsOut"], 0, 96, settings.gaps_out);
    settings.border_size = int_at(config, &["hyprland", "borderSize"], 0, 12, settings.border_size);
    settings.rounding = int_at(config, &["hyprland", "rounding"], 0, 48, settings.rounding);
    settings.blur = get_path(config, &["hyprland", "blur"])
        .and_then(Value::as_bool)
        .unwrap_or(true);
    settings.shadows = get_path(config, &["hyprland", "shadows"])
        .and_then(Value::as_bool)
        .unwrap_or(true);
    settings.animation_preset = get_path(config, &["hyprland", "animationPreset"])
        .and_then(Value::as_str)
        .unwrap_or("aether")
        .to_string();
    settings
}

fn int_at(config: &Value, path: &[&str], low: i64, high: i64, fallback: i64) -> i64 {
    let value = get_path(config, path)
        .and_then(|v| v.as_i64().or_else(|| v.as_f64().map(|f| f as i64)))
        .unwrap_or(fallback);
    value.clamp(low, high)
}

#[derive(Debug, Clone)]
pub struct HyprColors {
    pub primary: String,
    pub outline: String,
}

impl Default for HyprColors {
    fn default() -> Self {
        Self {
            primary: "#A99BFF".into(),
            outline: "#394154".into(),
        }
    }
}

pub fn colors_from_source(source: &Source, theme_id: &str, theme_file: &str) -> HyprColors {
    let text = source
        .read_to_string(&format!("themes/{theme_file}"))
        .or_else(|_| source.read_to_string(&format!("themes/{theme_id}.json")));
    let Ok(text) = text else {
        return HyprColors::default();
    };
    let Ok(value) = serde_json::from_str::<Value>(&text) else {
        return HyprColors::default();
    };
    HyprColors {
        primary: string_at(&value, &["colors", "primary"], "#A99BFF"),
        outline: string_at(&value, &["colors", "outline"], "#394154"),
    }
}

fn string_at(value: &Value, path: &[&str], fallback: &str) -> String {
    get_path(value, path)
        .and_then(Value::as_str)
        .unwrap_or(fallback)
        .to_string()
}

fn hex_to_rgba(value: &str, alpha: u8) -> String {
    let (r, g, b) = hex_rgb(value);
    format!("rgba({r:02X}{g:02X}{b:02X}{alpha:02X})")
}

pub fn generate(settings: &HyprSettings, colors: &HyprColors) -> String {
    let active = hex_to_rgba(&colors.primary, 255);
    let inactive = hex_to_rgba(&colors.outline, 0xAA);
    let animation = animation_block(&settings.animation_preset);
    let lines = vec![
        "# AETHER generated Hyprland include.".to_string(),
        "# Do not edit by hand: change AETHER Settings -> Hyprland and run".to_string(),
        "#   aether hyprland --apply".to_string(),
        String::new(),
        "general {".to_string(),
        format!("    gaps_in = {}", settings.gaps_in),
        format!("    gaps_out = {}", settings.gaps_out),
        format!("    border_size = {}", settings.border_size),
        format!("    col.active_border = {active}"),
        format!("    col.inactive_border = {inactive}"),
        "}".to_string(),
        String::new(),
        "decoration {".to_string(),
        format!("    rounding = {}", settings.rounding),
        "    active_opacity = 1.0".to_string(),
        "    inactive_opacity = 0.97".to_string(),
        "    blur {".to_string(),
        format!(
            "        enabled = {}",
            if settings.blur { "true" } else { "false" }
        ),
        "        size = 8".to_string(),
        "        passes = 3".to_string(),
        "        new_optimizations = true".to_string(),
        "        xray = true".to_string(),
        "    }".to_string(),
        "    shadow {".to_string(),
        format!(
            "        enabled = {}",
            if settings.shadows { "true" } else { "false" }
        ),
        "        range = 24".to_string(),
        "        render_power = 3".to_string(),
        "        color = rgba(00000055)".to_string(),
        "    }".to_string(),
        "}".to_string(),
        String::new(),
        animation.trim_end().to_string(),
        String::new(),
        "# AETHER layer surfaces: translucent bar, overlays and notifications.".to_string(),
        "layerrule = blur, aether-bar".to_string(),
        "layerrule = ignorezero, aether-bar".to_string(),
        "layerrule = blur, aether-overlay".to_string(),
        "layerrule = ignorezero, aether-overlay".to_string(),
        "layerrule = blur, aether-osd".to_string(),
        "layerrule = ignorezero, aether-osd".to_string(),
        "layerrule = blur, aether-notifications".to_string(),
        "layerrule = ignorezero, aether-notifications".to_string(),
        String::new(),
        "# Applications built with AETHER use rounded, translucent surfaces.".to_string(),
        "windowrulev2 = opacity 0.98 0.94, class:^(aether-.*)$".to_string(),
        format!(
            "windowrulev2 = rounding {}, class:^(aether-.*)$",
            settings.rounding
        ),
        String::new(),
    ];
    lines.join("\n")
}

fn animation_block(preset: &str) -> String {
    if preset == "off" || preset == "reduced" {
        return "animations {\n    enabled = false\n}\n".into();
    }
    let (curve, windows, workspaces, layers) = if preset == "snappy" {
        (
            "snappy, 0.2, 0.9, 0.2, 1.0",
            "animation = windows, 1, 3, snappy, popin 90%",
            "animation = workspaces, 1, 3, snappy, slide",
            "animation = layers, 1, 3, snappy, slide",
        )
    } else {
        (
            "aether, 0.22, 0.9, 0.22, 1.0",
            "animation = windows, 1, 5, aether, popin 92%",
            "animation = workspaces, 1, 5, aether, slide",
            "animation = layers, 1, 4, aether, slide",
        )
    };
    format!(
        "animations {{\n    enabled = true\n    bezier = {curve}\n    {windows}\n    {workspaces}\n    {layers}\n    animation = fade, 1, 5, aether\n    animation = border, 1, 5, aether\n}}\n"
    )
}

pub struct HyprOutcome {
    pub generated: PathBuf,
    pub main_changed: bool,
    pub backup: Option<PathBuf>,
}

pub fn install_static(
    source: &Source,
    paths: &Paths,
    dry_run: bool,
    reporter: &mut dyn Reporter,
) -> Result<PathBuf> {
    let target = paths.hypr_dir().join("aether/aether.conf");
    let bytes = source.read("hypr/aether.conf")?;
    if dry_run {
        reporter.line(
            LogLevel::DryRun,
            &format!("would write AETHER keybind config to {}", target.display()),
        );
        return Ok(target);
    }
    if target.exists() {
        let existing = fs::read(&target).unwrap_or_default();
        if existing != bytes {
            let backup = fsutil::backup_file(&target, &paths.hypr_dir().join("aether/backups"))?;
            reporter.line(
                LogLevel::Info,
                &format!(
                    "backed up {} to {}",
                    target.display(),
                    backup
                        .map(|p| p.display().to_string())
                        .unwrap_or_default()
                ),
            );
        }
    }
    fsutil::atomic_write(&target, &bytes, Some(0o644))?;
    reporter.line(
        LogLevel::Success,
        &format!("wrote {}", target.display()),
    );
    Ok(target)
}

pub fn apply(
    paths: &Paths,
    settings: &HyprSettings,
    colors: &HyprColors,
    manage_include: bool,
    dry_run: bool,
    reporter: &mut dyn Reporter,
) -> Result<HyprOutcome> {
    let generated = paths.hypr_dir().join("aether/generated.conf");
    let config = generate(settings, colors);
    if dry_run {
        reporter.line(
            LogLevel::DryRun,
            &format!(
                "would write generated Hyprland settings to {}",
                generated.display()
            ),
        );
        if manage_include {
            reporter.line(
                LogLevel::DryRun,
                &format!(
                    "would add a managed include to {}",
                    paths.hypr_dir().join("hyprland.conf").display()
                ),
            );
        }
        return Ok(HyprOutcome {
            generated,
            main_changed: false,
            backup: None,
        });
    }
    if generated.exists() {
        let old = fs::read_to_string(&generated).unwrap_or_default();
        if old != config {
            fsutil::backup_file(&generated, &paths.hypr_dir().join("aether/backups"))?;
        }
    }
    fsutil::atomic_write(&generated, config.as_bytes(), Some(0o644))?;
    reporter.line(
        LogLevel::Success,
        &format!("wrote generated Hyprland settings to {}", generated.display()),
    );
    let mut main_changed = false;
    let mut backup = None;
    if manage_include {
        let main = paths.hypr_dir().join("hyprland.conf");
        let result = ensure_include(&main, &generated, &paths.hypr_dir().join("aether/backups"))?;
        main_changed = result.changed;
        backup = result.backup;
        reporter.line(
            if result.changed {
                LogLevel::Success
            } else {
                LogLevel::Info
            },
            &result.message,
        );
    }
    Ok(HyprOutcome {
        generated,
        main_changed,
        backup,
    })
}

#[derive(Debug, Clone)]
pub struct IncludeOutcome {
    pub changed: bool,
    pub backup: Option<PathBuf>,
    pub message: String,
}

pub fn ensure_include(main_conf: &Path, generated: &Path, backup_dir: &Path) -> Result<IncludeOutcome> {
    if !main_conf.exists() {
        return Ok(IncludeOutcome {
            changed: false,
            backup: None,
            message: format!(
                "{} does not exist; generated settings were not sourced. Add: source = {}",
                main_conf.display(),
                generated.display()
            ),
        });
    }
    let text = fs::read_to_string(main_conf)
        .with_context(|| format!("could not read {}", main_conf.display()))?;
    if include_present(&text) {
        return Ok(IncludeOutcome {
            changed: false,
            backup: None,
            message: "AETHER include is already present in hyprland.conf".into(),
        });
    }
    let backup = fsutil::backup_file(main_conf, backup_dir)?;
    let block = format!(
        "\n{BEGIN_MARK}\nsource = {}\n{END_MARK}\n",
        generated.display()
    );
    let updated = format!("{}\n{}", text.trim_end(), block);
    fsutil::atomic_write(main_conf, updated.as_bytes(), None)?;
    Ok(IncludeOutcome {
        changed: true,
        backup: backup.clone(),
        message: format!(
            "added AETHER managed include to {}{}",
            main_conf.display(),
            backup
                .map(|p| format!(" (backup: {})", p.display()))
                .unwrap_or_default()
        ),
    })
}

pub fn include_present(text: &str) -> bool {
    text.contains(BEGIN_MARK)
        || text.lines().any(|line| {
            let trimmed = line.trim();
            trimmed.starts_with("source") && trimmed.contains("aether/generated.conf")
        })
}

pub fn remove_managed_include(
    main_conf: &Path,
    backup_dir: &Path,
    dry_run: bool,
    reporter: &mut dyn Reporter,
) -> Result<bool> {
    if !main_conf.exists() {
        reporter.line(
            LogLevel::Info,
            "hyprland.conf not found; nothing to remove",
        );
        return Ok(false);
    }
    let text = fs::read_to_string(main_conf)
        .with_context(|| format!("could not read {}", main_conf.display()))?;
    let Some(updated) = strip_managed_block(&text) else {
        reporter.line(
            LogLevel::Info,
            "no AETHER managed block found in hyprland.conf; leaving the file untouched",
        );
        return Ok(false);
    };
    if dry_run {
        reporter.line(
            LogLevel::DryRun,
            &format!(
                "would remove the AETHER managed include from {}",
                main_conf.display()
            ),
        );
        return Ok(true);
    }
    let backup = fsutil::backup_file(main_conf, backup_dir)?;
    fsutil::atomic_write(main_conf, updated.as_bytes(), None)?;
    reporter.line(
        LogLevel::Success,
        &format!(
            "removed AETHER managed include from {}{}",
            main_conf.display(),
            backup
                .map(|p| format!(" (backup: {})", p.display()))
                .unwrap_or_default()
        ),
    );
    Ok(true)
}

/// Remove every marked AETHER block. Returns `None` when no block exists.
pub fn strip_managed_block(text: &str) -> Option<String> {
    let mut output = String::new();
    let mut cursor = 0;
    let mut found = false;
    while let Some(relative_start) = text[cursor..].find(BEGIN_MARK) {
        let start = cursor + relative_start;
        let Some(relative_end) = text[start..].find(END_MARK) else {
            break;
        };
        let end = start + relative_end + END_MARK.len();
        output.push_str(&text[cursor..start]);
        cursor = end;
        found = true;
    }
    if !found {
        return None;
    }
    output.push_str(&text[cursor..]);
    Some(output.trim_end().to_string() + "\n")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::report::BufferReporter;

    #[test]
    fn generated_config_contains_core_values() {
        let settings = HyprSettings {
            gaps_in: 4,
            rounding: 20,
            blur: false,
            ..Default::default()
        };
        let text = generate(&settings, &HyprColors::default());
        assert!(text.contains("gaps_in = 4"));
        assert!(text.contains("rounding = 20"));
        assert!(text.contains("enabled = false"));
        assert!(text.contains("col.active_border = rgba(A99BFF"));
        assert!(text.contains("source") == false);
    }

    #[test]
    fn include_is_added_once_and_removed() {
        let dir = tempfile::tempdir().unwrap();
        let main = dir.path().join("hyprland.conf");
        let generated = dir.path().join("aether/generated.conf");
        fs::write(&main, "monitor=,preferred,auto,1\n").unwrap();
        let backups = dir.path().join("aether/backups");
        let first = ensure_include(&main, &generated, &backups).unwrap();
        assert!(first.changed);
        assert!(first.backup.unwrap().exists());
        let second = ensure_include(&main, &generated, &backups).unwrap();
        assert!(!second.changed);
        let text = fs::read_to_string(&main).unwrap();
        assert_eq!(text.matches(BEGIN_MARK).count(), 1);
        assert!(text.contains("monitor=,preferred,auto,1"));

        let mut reporter = BufferReporter::default();
        assert!(remove_managed_include(&main, &backups, false, &mut reporter).unwrap());
        let text = fs::read_to_string(&main).unwrap();
        assert!(!text.contains(BEGIN_MARK));
        assert!(text.contains("monitor=,preferred,auto,1"));
    }

    #[test]
    fn stripping_preserves_surrounding_text() {
        let text = format!("before\n{BEGIN_MARK}\nsource = /x\n{END_MARK}\nafter\n");
        let result = strip_managed_block(&text).unwrap();
        assert_eq!(result, "before\n\nafter\n");
        assert!(strip_managed_block("nothing").is_none());
    }
}
